function isMobile(){return/Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent)||window.innerWidth<=768}function handleEmailClick(e){e.preventDefault(),isMobile()?window.location.href="mailto:contato@emporioipiatti.com.br":window.open("https://mail.google.com/mail/u/0/?fs=1&to=contato@emporioipiatti.com.br&tf=cm","_blank")}function updateEmailLink(){const e=document.getElementById("email-link");e&&(e.href=isMobile()?"mailto:contato@emporioipiatti.com.br":"#")}document.addEventListener("DOMContentLoaded",updateEmailLink),window.addEventListener("resize",updateEmailLink);
